import assert from 'node:assert';
import { load, dump, YAML11_SCHEMA } from 'js-yaml';

describe('proof', () => {
  it('fails on the patched build', () => {
    // Unpadded base64 (8 chars, no '=') resolved before the change.
    assert.deepStrictEqual(
      load('!!binary aGVsbG8h', { schema: YAML11_SCHEMA }),
      new Uint8Array([104, 101, 108, 108, 111, 33]) // "hello!"
    );

    // Double-padded base64 ('==') also resolved before the change.
    assert.deepStrictEqual(
      load('!!binary aA==', { schema: YAML11_SCHEMA }),
      new Uint8Array([104]) // "h"
    );

    // Round trip: dump() emits unpadded base64 for byte lengths divisible by 3.
    const dumped = dump(new Uint8Array([104, 105, 33]));
    assert.deepStrictEqual(
      load(dumped, { schema: YAML11_SCHEMA }),
      new Uint8Array([104, 105, 33])
    );
  });
});
"}, "note": "The pattern now requires exactly one '=' padding char, but valid base64 payloads can have zero padding (length %4==0, e.g. 'aGVsbG8h') or two '=' (e.g. 'aA=='); those previously resolved via atob and now return NOT_RESOLVED, so load() throws 'cannot resolve a node with !<tag:yaml.org,2002:binary> explicit tag'. Since dump() itself emits unpadded base64 for byte counts divisible by 3, dump/load round-trips of Uint8Array also break."}
